/// <summary>
/// MPJ_24248 Price Data Feed.
/// Simulated Auto charges
/// Parts of code used here are based on standard code found in class GUPAutoChargeMatchingHelper.
/// GUPAutoChargeMatchingHelper is marked as Internal and cant be called directly. As at 20/12/2022
/// </summary>
public class METSimulatedAutoCharges
{
    public RetailPricingSimulatorSalesLine          simSalesLine;
    public RetailPricingSimulatorSalesTransaction   simSalesTransaction;
    public CustTable                                custTable;
    public InventTable                              inventTable;
    public SalesTable                               salesTable;
    public SalesLine                                salesLine;
    public MarkupTransInsertParameters              parameters;
    public TransDate                                priceDate;
    
}

Method.Source:
    /// <summary>
    /// Construct new object from simulated Sales line
    /// </summary>
    /// <param name = "_simSalesLine">simulated Sales line</param>
    /// <returns>new METSimulatedAutoCharges</returns>
    public static METSimulatedAutoCharges newFromSimSalesLine(RetailPricingSimulatorSalesLine _simSalesLine)
    {
        METSimulatedAutoCharges simulatedAutoCharges = new METSimulatedAutoCharges();
        
        simulatedAutoCharges.simSalesLine           = _simSalesLine;
        simulatedAutoCharges.simSalesTransaction    = RetailPricingSimulatorSalesTransaction::findByRef(_simSalesLine.RetailPricingSimulatorSalesTransaction);
        simulatedAutoCharges.custTable              = CustTable::find(simulatedAutoCharges.simSalesTransaction.CustAccount);
        simulatedAutoCharges.inventTable            = InventTable::findByProduct(_simSalesLine.Product);

        simulatedAutoCharges.BuildSalesTableTmp();
        simulatedAutoCharges.BuildSalesLineTmp();

        simulatedAutoCharges.priceDate = DateTimeUtil::date(simulatedAutoCharges.simSalesTransaction.SimulationDateTime);

        return simulatedAutoCharges;
    }

    /// <summary>
    /// Construct new object from simulated Sales Table and Sales line
    /// </summary>
    /// <param name = "_salesTable">Sales table</param>
    /// <param name = "_salesLine">Sales line</param>
    /// <returns>new METSimulatedAutoCharges</returns>
    public static METSimulatedAutoCharges newFromSalesTmp(SalesTable _salesTable, SalesLine _salesLine)
    {
        METSimulatedAutoCharges simulatedAutoCharges = new METSimulatedAutoCharges();

        simulatedAutoCharges.salesTable = _salesTable;
        simulatedAutoCharges.salesLine  = _salesLine;

        simulatedAutoCharges.PriceDate = _salesTable.ShippingDateRequested;

        return simulatedAutoCharges;
    }

    /// <summary>
    /// get a list of markup lines
    /// </summary>
    /// <returns>List of markup lines</returns>
    public List getMarkupAutoLines()
    {
        List        MatchedAutoChargeLineRecIdList;

        this.BuildParameterLines();

        //86376: Price01 Simulator error - replaced custom method with calling the standard classes to get auto charges
        //MatchedAutoChargeLineRecIdList = this.findAllMatchedAutoChargesLines();
        GUPRetailPricingDataManagerPricingRuleCache pricingRuleCache = new GUPRetailPricingDataManagerPricingRuleCache();
        pricingRuleCache.loadPricingRuleDataForAutoChargesLine();
        GUPChargeMatchingHelper matchinghelper = GUPChargeMatchingHelper::construct();
        MatchedAutoChargeLineRecIdList = matchinghelper.findAllMatchedAutoChargesLines(this.BuildParameterLines(), pricingRuleCache);

        return MatchedAutoChargeLineRecIdList;
    }

    /// <summary>
    /// get a list of Markup lines for header level 
    /// </summary>
    /// <returns>List of records</returns>
    public List getMarkupAutoHeaders()
    {
        List        MatchedAutoChargeHeaderRecIdList;

        this.BuildParameterHeaders();

        MatchedAutoChargeHeaderRecIdList = this.findAllMatchedAutoChargesHeaders();

        return MatchedAutoChargeHeaderRecIdList;
    }

    /// <summary>
    /// construct a sales table record
    /// </summary>
    /// <returns>sales table</returns>
    public SalesTable BuildSalesTableTmp()
    {
        salesTable.clear();
        salesTable.initValue();
        salesTable.SalesId       = guid2Str(newGuid()); //dont consume genuine salesId from Number seq as this is only a temp record.
        salesTable.CustAccount   = simSalesTransaction.CustAccount;
        salesTable.initFromCustTable();
        salesTable.CurrencyCode  = simSalesTransaction.ChannelCurrency ? simSalesTransaction.ChannelCurrency : salesTable.CurrencyCode;

        return salesTable;
    }

    /// <summary>
    /// construct a sales line record
    /// </summary>
    /// <returns>sales line</returns>
    public SalesLine BuildSalesLineTmp()
    {
        salesLine.clear();
        salesLine.salesId    = salesTable.SalesId;
        salesLine.ItemId     = inventTable.itemId;
        
        salesLine.initFromSalesTable(salesTable, false);
        salesLine.initLineFromItemOrCategory();
        salesLine.InventDimId = simSalesLine.InventDimId;
        salesLine.SalesQty    = simSalesLine.Quantity;
        salesLine.LineAmount  = simSalesLine.SalesPrice;
        salesLine.SalesPrice  = salesLine.LineAmount / salesLine.SalesQty;
        salesLine.InventTransId = guid2Str(newGuid()); //dont consume genuine InventTransId from Number seq as this is only a temp record.

        return salesLine;
    }

    /// <summary>
    /// construct parameters object
    /// </summary>
    /// <returns>parameters object</returns>
    public MarkupTransInsertParameters BuildParameterLines()
    {
        parameters  = MarkupTransInsertParameters::construct();
        InventDim                   inventDim   = InventDim::find(salesLine.InventDimId);

        Parameters.ModuleCategory   = HeadingLine::Line;
        Parameters.ModuleType       = MarkupModuleType::Cust;
        Parameters.Source           = salesLine;
        Parameters.Account          = salesTable.markupCustomerAccount();
        Parameters.AccountGroup     = salesTable.MarkupGroup;
        Parameters.Currency         = salesTable.CurrencyCode;
        Parameters.LanguageId       = salesTable.LanguageId;
        Parameters.Item             = salesLine.itemId;
        Parameters.InventSiteId     = inventDim.InventSiteId;
        Parameters.InventLocationId = inventDim.InventLocationId;
        Parameters.ItemGroup        = inventTable.salesMarkupGroup();
        Parameters.InvertSign       = false;
        Parameters.DeleteExistingMarkupTrans = true;
        Parameters.DlvModeId        = salesLine.dlvMode;
        Parameters.DlvModeGroup     = DlvMode::find(salesLine.DlvMode).MarkupGroup;
        Parameters.TotalAmount      = salesLine.LineAmount;
        Parameters.McrReturnMarkup  = NoYes::No;

        return Parameters;
    }

    /// <summary>
    /// construct parameters object
    /// </summary>
    /// <returns>parameters object</returns>
    public MarkupTransInsertParameters BuildParameterHeaders()
    {
        parameters  = MarkupTransInsertParameters::construct();

        Parameters.ModuleCategory   = HeadingLine::Heading;
        Parameters.ModuleType       = MarkupModuleType::Cust;
        Parameters.Source           = salesTable;
        Parameters.Account          = salesTable.markupCustomerAccount();
        Parameters.AccountGroup     = salesTable.MarkupGroup;
        Parameters.Currency         = salesTable.CurrencyCode;
        Parameters.LanguageId       = salesTable.LanguageId;
        Parameters.Item             = METConstants::emptyString;
        Parameters.InventSiteId     = salesTable.InventSiteId;
        Parameters.InventLocationId = salesTable.InventLocationId;
        Parameters.ItemGroup        = METConstants::emptyString;
        Parameters.InvertSign       = false;
        Parameters.DeleteExistingMarkupTrans = true;
        Parameters.DlvModeId        = salesTable.dlvMode;
        Parameters.DlvModeGroup     = DlvMode::find(salesTable.dlvMode).MarkupGroup;
        Parameters.TotalAmount      = salesLine.LineAmount;
        Parameters.McrReturnMarkup  = NoYes::No;

        return Parameters;
    }

    /// <summary>
    /// Find Auto charge lines for a given Sales Table record
    /// Based on standard code. class GUPAutoChargeMatchingHelper.findAllMatchedAutoChargesLines()
    /// </summary>
    /// <returns>list of header charges</returns>
    public List findAllMatchedAutoChargesHeaders()
    {
        //TODO: inmcomplete. Standard code has been changed. Below code doesnt work
        List matchedMarkupAutoTable = new List(Types::String);
        CLRObject autoChargeEntities = GUPMatchingEntityHelper::createCLRList(new GUPMatchingEntityAutoCharge());

        Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter();
        
        MarkupAutoTable             markupAutoTable;
        MarkupAutoLine              markupAutoLine;

        GUPPriceComponentCodeSetup  priceComponentCodeSetup;

        SalesTable                  salesTableloc = parameters.Source;
        
        while select markupAutoTable
                where markupAutoTable.ModuleType == MarkupModuleType::Cust
                    && markupAutoTable.ModuleCategory == HeadingLine::Heading
                    && markupAutoTable.IsGupMarkupAuto == NoYes::Yes
                join CalculationSequence 
                from priceComponentCodeSetup
                order by priceComponentCodeSetup.CalculationSequence
                where markupAutoTable.PriceComponentCodeName == priceComponentCodeSetup.PriceComponentCodeName
                    && priceComponentCodeSetup.PricingTreeName == ''
        {
            GUPMatchingEntityAutoCharge MatchEntityAutoCharge = new GUPMatchingEntityAutoCharge();
            matchEntityAutoCharge.init(markupAutoTable, priceComponentCodeSetup.CalculationSequence);
            autoChargeEntities.add(MatchEntityAutoCharge);
        }           

        if (autoChargeEntities.get_Count())
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction salesTransaction = RetailPricingEngineHelper::getSalesTransactionFromOrder(salesTableloc);
            salesTransaction.SalesId = salesTableloc.SalesId;

            var result = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AttributePricingPropertiesMatcher::GetMasterDataMatchedByTransactionWithNoSalesLine(salesTransaction,
                                                                                                                                                                        GUPMatchingEntityHelper::initializeDataAcessor(salesTableloc.SalesId),
                                                                                                                                                                        autoChargeEntities);

            var listEnumerator = result.GetEnumerator();
            while(listEnumerator.moveNext())
            {
                matchedMarkupAutoTable.addEnd(listEnumerator.get_Current().id);
            }
        }
        
        return matchedMarkupAutoTable;
    }

    /// <summary>
    /// Find Auto charge lines for a given Sales Table and Sales line records
    /// Based on standard code. class GUPAutoChargeMatchingHelper.findAllMatchedAutoChargesLines()
    /// </summary>
    /// <returns>list of header charges</returns>
    public List findAllMatchedAutoChargesLines()
    {
        List        MatchedMarkupAutoLine = new List(Types::String);
        CLRObject   AutoChargeEntities   = GUPMatchingEntityHelper::createCLRList(new GUPMatchingEntityAutoCharge());

        try
        {
            Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter UnifiedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter();

            MarkupAutoLine              MarkupAutoLine;
            MarkupAutoTable             MarkupAutoTable;
            GUPPriceComponentCodeSetup  PriceComponentCodeSetup;
            GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
            SalesLine                   salesLineLoc = parameters.Source;
            InventTransId               InventTransId = salesLineLoc.InventTransId;

            while select CalculationSequence from priceComponentCodeSetup
                order by priceComponentCodeSetup.CalculationSequence, groupCombination.Priority
                where priceComponentCodeSetup.PriceComponent == GUPPriceComponent::AutoCharges
                join RecId from markupAutoTable
                    where markupAutoTable.PriceComponentCodeName  == priceComponentCodeSetup.PriceComponentCodeName
                       && priceComponentCodeSetup.PricingTreeName == ''
                       && markupAutoTable.ModuleType      == MarkupModuleType::Cust
                       && markupAutoTable.ModuleCategory  == HeadingLine::Line
                       && markupAutoTable.IsGupMarkupAuto == NoYes::Yes
                join markupAutoLine
                    where markupAutoLine.TableRecId      == markupAutoTable.RecId
                       && markupAutoLine.CurrencyCode    == parameters.Currency
                       && markupAutoLine.MCRReturnMarkup == parameters.McrReturnMarkup
                       && (markupAutoLine.InventSiteId == ''     || markupAutoLine.InventSiteId == parameters.InventSiteId)
                       && (markupAutoLine.InventLocationId == '' || markupAutoLine.InventLocationId == parameters.InventLocationId)
                       && (markupAutoLine.FromDate <= priceDate  || markupAutoLine.FromDate == dateNull())
                       && (markupAutoLine.ToDate >= priceDate    || markupAutoLine.ToDate == dateNull())
                outer join Priority from groupCombination
                    where groupCombination.RecId == markupAutoLine.PriceAttributeGroupCombinationRecId
            {
                GUPMatchingEntityAutoCharge MatchEntityAutoCharge = new GUPMatchingEntityAutoCharge();
                MatchEntityAutoCharge.initFromMarkupAutoLine(MarkupAutoLine);
                AutoChargeEntities.add(MatchEntityAutoCharge);
            }

            if (AutoChargeEntities.get_Count())
            {
                CLRObject SalesLineIdSet = GUPMatchingEntityHelper::createCLRStringSet();
                SalesLineIdSet.add(InventTransId);
                Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction SalesTransaction = RetailPricingEngineHelper::getSalesTransactionFromOrder(salesTable, salesLine);
                SalesTransaction.SalesId = salesTable.SalesId;

                var result = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AttributePricingPropertiesMatcher::GetMasterDataMatchedByTransaction(SalesTransaction,
                                                                                                                                                                GUPMatchingEntityHelper::initializeDataAcessor(salesTable.SalesId),
                                                                                                                                                                UnifiedPricingParameter,
                                                                                                                                                                AutoChargeEntities,
                                                                                                                                                                SalesLineIdSet);

                var listEnumerator = result.get_Item(inventTransId).GetEnumerator();
                while(listEnumerator.moveNext())
                {
                    matchedMarkupAutoLine.addEnd(listEnumerator.get_Current().id);
                }
            }
        }
        catch
        {
            error("@MET:AutoChargesSimulationFailed");
        }

        return matchedMarkupAutoLine;
    }

    /// <summary>
    /// init markup trans
    /// </summary>
    /// <param name = "_markupAutoLine">markup line</param>
    /// <returns>markup transaction</returns>
    public MarkupTrans initializeMarkupTransFromParent(MarkupAutoLine _markupAutoLine)
    {
        MarkupTrans markupTrans;
        markupTrans.initFromMarkupTable(_markupAutoLine.markupTable());
        markupTrans.initFromMarkupAutoLine(_markupAutoLine);
        //markupTrans.initSequenceCompoundSpecificUoMFromMarkupAutoLine(markupAutoLine, parent);
        markupTrans.initFromCaller(simSalesLine.TableId, simSalesLine);
        markupTrans.MCRInstallmentEligible = false;

        if (_markupAutoLine.MarkupCurrencyCode)
        {
            markupTrans.CurrencyCode = _markupAutoLine.MarkupCurrencyCode;
        }

        markupTrans.TransTableId   = simSalesLine.TableId;
        markupTrans.TransRecId     = simSalesLine.RecId;
        markupTrans.LineNum        = MarkupTrans::lastLineNum(simSalesLine.TableId, simSalesLine.RecId) + 1;

        if (parameters.ModuleType == MarkupModuleType::Delivery)
        {
            markupTrans.ModuleType = MarkupModuleType::Delivery;
        }

        if (parameters.invertSign &&
            markupTrans.MarkupCategory == MarkupCategory::Fixed)
        {
            markupTrans.Value = -markupTrans.Value;
        }

        if (parameters.LanguageId)
        {
            markupTrans.Txt = LanguageTxt::languageId(tableNum(MarkupAutoTable), _markupAutoLine.RecId, parameters.LanguageId);
        }

        if (!markupTrans.Txt)
        {
            markupTrans.Txt = MarkupTable::find(_markupAutoLine.ModuleType, _markupAutoLine.MarkupCode).Txt;
        }

        markupTrans.IsAutoCharge = NoYes::Yes;
        
        return markupTrans;
    }
